function topView(root) {
  const all = [];                            // [column, depth, visit order, value] for every node
  let order = 0;
  function dfs(node, col, depth) {
    if (node === null) return;
    all.push([col, depth, order++, node.val]);
    dfs(node.left, col - 1, depth + 1);
    dfs(node.right, col + 1, depth + 1);
  }
  dfs(root, 0, 0);
  all.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);   // by column, then height
  const view = [];
  for (let i = 0; i < all.length; i++) {
    if (i === 0 || all[i][0] !== all[i - 1][0]) view.push(all[i][3]);   // first of each column
  }
  return view;
}

