    all.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
    List<Integer> view = new ArrayList<>();
    for (int i = 0; i < all.size(); i++) {
        if (i == 0 || all.get(i)[0] != all.get(i - 1)[0]) view.add(all.get(i)[3]);   // first of each column
