function topView(root) {
  const top = new Map();                     // column -> [depth, value] of the highest node so far
  function dfs(node, col, depth) {
    if (node === null) return;
    if (!top.has(col) || depth < top.get(col)[0]) top.set(col, [depth, node.val]);   // higher than before?
    dfs(node.left, col - 1, depth + 1);
    dfs(node.right, col + 1, depth + 1);
  }
  dfs(root, 0, 0);
  return [...top.keys()].sort((a, b) => a - b).map((col) => top.get(col)[1]);
}

