public List<Integer> topView(TreeNode root) {
    TreeMap<Integer, int[]> top = new TreeMap<>();   // column -> {depth, value}, kept sorted by column
    dfs(root, 0, 0, top);
    List<Integer> view = new ArrayList<>();
    for (int[] entry : top.values()) view.add(entry[1]);
    return view;
}

