    dfs(node.left, col - 1, depth + 1, top);
    dfs(node.right, col + 1, depth + 1, top);
}

void dfs(TreeNode* node, int col, int depth, map<int, pair<int, int>>& top) {
    if (node == nullptr) return;
    auto it = top.find(col);
    if (it == top.end() || depth < it->second.first) top[col] = {depth, node->val};   // higher than before?
    dfs(node->left, col - 1, depth + 1, top);
    dfs(node->right, col + 1, depth + 1, top);
}

