    map<int, pair<int, int>> top;            // column -> (depth, value), kept sorted by column
    dfs(root, 0, 0, top);
    vector<int> view;
    for (const auto& [col, entry] : top) view.push_back(entry.second);
    return view;
}

function topView(root) {
  if (root === null) return [];
  const first = new Map();                   // column -> first value seen there
  let minCol = 0, maxCol = 0;
  const queue = [[root, 0]];
  while (queue.length > 0) {
    const [node, col] = queue.shift();
    if (!first.has(col)) first.set(col, node.val);   // BFS meets the highest node first
    minCol = Math.min(minCol, col);
    maxCol = Math.max(maxCol, col);
    if (node.left) queue.push([node.left, col - 1]);
    if (node.right) queue.push([node.right, col + 1]);
  }
  const view = [];
  for (let c = minCol; c <= maxCol; c++) view.push(first.get(c));
  return view;
}

from collections import deque

def top_view(root):
    if root is None:
        return []
    first = {}                               # column -> first value seen there
    min_col = max_col = 0
    queue = deque([(root, 0)])
    while queue:
        node, col = queue.popleft()
        if col not in first:
            first[col] = node.val            # BFS meets the highest node first
        min_col = min(min_col, col)
        max_col = max(max_col, col)
        if node.left:
            queue.append((node.left, col - 1))
        if node.right:
            queue.append((node.right, col + 1))
    return [first[c] for c in range(min_col, max_col + 1)]

public List<Integer> topView(TreeNode root) {
    List<Integer> view = new ArrayList<>();
    if (root == null) return view;
    Map<Integer, Integer> first = new HashMap<>();   // column -> first value seen there
    int minCol = 0, maxCol = 0;
    Queue<TreeNode> nodes = new ArrayDeque<>();
    Queue<Integer> cols = new ArrayDeque<>();
    nodes.offer(root);
    cols.offer(0);
    while (!nodes.isEmpty()) {
        TreeNode node = nodes.poll();
        int col = cols.poll();
        first.putIfAbsent(col, node.val);            // BFS meets the highest node first
        minCol = Math.min(minCol, col);
        maxCol = Math.max(maxCol, col);
        if (node.left != null) { nodes.offer(node.left); cols.offer(col - 1); }
        if (node.right != null) { nodes.offer(node.right); cols.offer(col + 1); }
    }
    for (int c = minCol; c <= maxCol; c++) view.add(first.get(c));
    return view;
}

vector<int> topView(TreeNode* root) {
    vector<int> view;
    if (root == nullptr) return view;
    unordered_map<int, int> first;           // column -> first value seen there
    int minCol = 0, maxCol = 0;
    queue<pair<TreeNode*, int>> q;
    q.push({root, 0});
    while (!q.empty()) {
        auto [node, col] = q.front();
        q.pop();
        first.emplace(col, node->val);       // only inserts if the column is new: BFS meets the highest first
        minCol = min(minCol, col);
        maxCol = max(maxCol, col);
        if (node->left) q.push({node->left, col - 1});
        if (node->right) q.push({node->right, col + 1});
    }
    for (int c = minCol; c <= maxCol; c++) view.push_back(first[c]);
    return view;
}
